    {
      "design": "r0A",
      "good": "The full table fits in the viewport, so all four metrics can be compared without horizontal scrolling. The short numeric rows are mostly compact.",
      "problems": "The header dominates the table and is difficult to scan because several words break across lines. LATAM also breaks, making the last row taller and weakening the row rhythm.",
      "cause": "At 65px, Region has only 44px for text, too little for both its header and LATAM. The metric columns provide only 44–61px of text width, forcing breaks inside long header words."
    },
    {
      "design": "r0B",
      "good": "Intact header words and uniformly compact data rows make the table much easier to read. Its four-line header is a reasonable compromise between height and width.",
      "problems": "The viewport cuts through the customer-count column and leaves the promoter-score column offscreen, so readers must scroll to complete each regional comparison.",
      "cause": "The first three columns use 276px, and the 110px customer column extends past the 360px viewport. The 477px table requires 117px of horizontal scrolling."
    },
    {
      "design": "r0C",
      "good": "The two-line headers are calm and easy to read, and the data rows retain a consistent rhythm.",
      "problems": "The wide table separates the metrics and puts both customer measures beyond the initial viewport. Readers must scroll almost a full viewport to see the right edge, making across-row comparisons more cumbersome.",
      "cause": "The 165px revenue, 145px growth, and 175px customer columns buy shorter headers at the cost of a 677px total width and 317px of overflow."
    }
  ],
  "done": false,
  "designs": [
    {
      "name": "compact-scroll",
      "widths": [71, 95, 82, 97, 88],
      "change": "Keep Region and every header word intact while reducing the table to 433px. This retains compact data rows and reduces scrolling relative to r0B, accepting taller headers."
    },
    {
      "name": "balanced-scroll",
      "widths": [71, 105, 95, 100, 88],
      "change": "Give the financial headers more room than in compact-scroll while keeping the customer columns close to their word-width minimums. The 459px total aims for a more even header rhythm with less scrolling than r0B."
    },
    {
      "name": "viewport-fit",
      "widths": [71, 72, 70, 78, 68],
